{"file_text": "/* ===== Chat Layout ===== */

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

/* ===== Channel Sidebar ===== */

.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background: #1a1d21;
    color: #ccc;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #333;
}

.sidebar-title {
    padding: 16px;
    margin: 0;
    font-size: 1rem;
    color: #fff;
    border-bottom: 1px solid #333;
}

.channel-list {
    flex: 1;
    overflow-y: auto;
}

.channel-item {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    width: 100%;
    padding: 10px 16px;
    background: none;
    border: none;
    color: #999;
    cursor: pointer;
    text-align: left;
    font-size: 0.9rem;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #27242c;
}

.channel-item.active {
    background: #1164a3;
    color: #fff;
}

.channel-item.active .channel-desc {
    color: rgba(255,255,255,0.7);
}

.channel-name {
    font-weight: 600;
    flex: 1;
}

.channel-desc {
    width: 100%;
    font-size: 0.75rem;
    color: #777;
    margin-top: 2px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    background: #e01e5a;
    color: #fff;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 2px 7px;
    border-radius: 10px;
    margin-left: 4px;
}

/* ===== Main Panel ===== */

.main-panel {
    flex: 1;
    display: flex;
    flex-direction: column;
    background: #fff;
    min-width: 0;
}

.main-panel.no-channel {
    align-items: center;
    justify-content: center;
    color: #888;
    font-size: 1.1rem;
}

/* ===== Message Area ===== */

.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
}

.message-area-header {
    padding: 12px 20px;
    border-bottom: 1px solid #e0e0e0;
}

.message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
}

.channel-description {
    margin: 2px 0 0;
    font-size: 0.8rem;
    color: #888;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 12px 20px;
}

.loading-indicator {
    text-align: center;
    padding: 8px;
    color: #888;
    font-size: 0.85rem;
}

/* ===== Chat Message ===== */

.chat-message {
    position: relative;
    padding: 8px 12px;
    border-radius: 6px;
    margin-bottom: 4px;
    transition: background 0.1s;
}

.chat-message.hovered {
    background: #f8f8f8;
}

.message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.message-author {
    font-weight: 700;
    font-size: 0.9rem;
}

.message-time {
    font-size: 0.75rem;
    color: #999;
}

.message-content {
    margin: 4px 0;
    font-size: 0.9rem;
    line-height: 1.45;
    white-space: pre-wrap;
}

/* ===== Reactions ===== */

.message-reactions {
    display: flex;
    flex-wrap: wrap;
    gap: 4px;
    margin-top: 4px;
}

.reaction-badge {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 2px 8px;
    font-size: 0.8rem;
    background: #f0f4ff;
    border: 1px solid #d0d8e8;
    border-radius: 12px;
    cursor: pointer;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #dce4f5;
}

/* ===== Thread Link ===== */

.thread-link {
    display: inline-block;
    margin-top: 4px;
    background: none;
    border: none;
    color: #1264a3;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    padding: 0;
}

.thread-link:hover {
    text-decoration: underline;
}

/* ===== Hover Actions ===== */

.message-actions {
    position: absolute;
    top: 4px;
    right: 8px;
    display: flex;
    gap: 4px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 6px;
    padding: 2px;
    box-shadow: 0 1px 4px rgba(0,0,0,0.1);
}

.action-btn {
    background: none;
    border: none;
    padding: 4px 8px;
    cursor: pointer;
    font-size: 0.78rem;
    border-radius: 4px;
    color: #555;
}

.action-btn:hover {
    background: #f0f0f0;
}

/* ===== Emoji Picker ===== */

.emoji-picker {
    position: absolute;
    top: -8px;
    right: 8px;
    transform: translateY(-100%);
    display: flex;
    gap: 2px;
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 6px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.15);
    z-index: 10;
}

.emoji-option {
    background: none;
    border: none;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 6px;
    border-radius: 4px;
    transition: background 0.1s;
}

.emoji-option:hover {
    background: #f0f0f0;
}

/* ===== Message Input ===== */

.message-input {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #e0e0e0;
    background: #fff;
}

.message-input textarea {
    flex: 1;
    resize: none;
    border: 1px solid #ccc;
    border-radius: 6px;
    padding: 8px 12px;
    font-size: 0.9rem;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input textarea:focus {
    border-color: #1264a3;
}

.send-btn {
    padding: 8px 20px;
    background: #007a5a;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.9rem;
    transition: background 0.15s;
    align-self: flex-end;
}

.send-btn:hover:not(:disabled) {
    background: #005e44;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

/* ===== Thread Panel ===== */

.thread-panel {
    width: 25%;
    min-width: 280px;
    border-left: 1px solid #e0e0e0;
    background: #fff;
    display: flex;
    flex-direction: column;
    height: 100vh;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
}

.thread-header h3 {
    margin: 0;
    font-size: 1rem;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #666;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #f0f0f0;
}

.thread-root-quote {
    margin: 12px 16px;
    padding: 10px 12px;
    background: #f8f8f8;
    border-left: 3px solid #1264a3;
    border-radius: 4px;
}

.quote-author {
    font-weight: 700;
    font-size: 0.85rem;
}

.quote-content {
    margin: 4px 0 0;
    font-size: 0.85rem;
    color: #444;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 0 16px;
}
